[
  {
    "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7594.md",
    "title": "EIP-7594: PeerDAS - Peer Data Availability Sampling",
    "category": "EIP",
    "type": "Standards Track / Core",
    "layer": "consensus+networking",
    "status": "success",
    "sub_graphs": [
      {
        "id": "SG-7594-001",
        "name": "1D Erasure Coding Extension",
        "description": "Extends EIP-4844 blobs using one-dimensional erasure coding. Each row consists of blob data combined with its erasure code, subdivided into cells (smallest authenticatable units via KZG commitments). Each column maps to a specific gossip subnet.",
        "invariants": [
          {
            "id": "INV-7594-001",
            "text": "A node can reconstruct the entire data matrix if it acquires at least 50% of all columns."
          },
          {
            "id": "INV-7594-002",
            "text": "Each cell MUST be authenticatable with its respective blob's KZG commitment."
          },
          {
            "id": "INV-7594-003",
            "text": "A maximum of 6 blobs per transaction MUST be enforced at submission time, when received from the network, and during block production and processing."
          }
        ],
        "pre_conditions": [
          {
            "id": "PRE-7594-001",
            "text": "EIP-4844 blob transactions must already be supported by the network."
          }
        ],
        "post_conditions": [
          {
            "id": "POST-7594-001",
            "text": "All blob data is available and reconstructible from at least 50% of columns."
          }
        ],
        "state_variables": [
          {
            "id": "SV-7594-001",
            "name": "CELLS_PER_EXT_BLOB",
            "description": "Number of cells for an extended blob, defined in consensus specs."
          },
          {
            "id": "SV-7594-002",
            "name": "NUMBER_OF_CUSTODY_GROUPS",
            "description": "Total number of samples possible (parameter m in security analysis)."
          },
          {
            "id": "SV-7594-003",
            "name": "SAMPLES_PER_SLOT",
            "description": "Minimum number of samples a node must download per slot (parameter k in security analysis)."
          }
        ],
        "functions": [],
        "data_structures": []
      },
      {
        "id": "SG-7594-002",
        "name": "Column-Based Custody and Sampling",
        "description": "Each node maintains a deterministic set of column subnets as a function of their node ID. Nodes find and maintain a diverse peer set and sample columns from peers to perform DAS every slot.",
        "invariants": [
          {
            "id": "INV-7594-004",
            "text": "Each node's custody set is deterministic as a function of their node ID."
          },
          {
            "id": "INV-7594-005",
            "text": "Validators have an additional custody requirement that scales with the validator count."
          }
        ],
        "pre_conditions": [],
        "post_conditions": [
          {
            "id": "POST-7594-002",
            "text": "Nodes can request missing columns (below 50% threshold) from peer nodes."
          }
        ],
        "state_variables": [],
        "functions": [],
        "data_structures": []
      },
      {
        "id": "SG-7594-003",
        "name": "Transaction Wrapper Modification (Networking)",
        "description": "Modifies the EIP-4844 transaction pool wrapper for blob transactions to include cell KZG proofs and a wrapper version, replacing the old proofs field.",
        "invariants": [
          {
            "id": "INV-7594-006",
            "text": "cell_proofs MUST contain exactly CELLS_PER_EXT_BLOB * len(blobs) cell proofs."
          },
          {
            "id": "INV-7594-007",
            "text": "KZG commitments MUST hash to the versioned hashes: kzg_to_versioned_hash(commitments[i]) == tx_payload_body.blob_versioned_hashes[i]."
          },
          {
            "id": "INV-7594-008",
            "text": "There MUST be an equal number of tx_payload_body.blob_versioned_hashes, blobs, and commitments."
          },
          {
            "id": "INV-7594-009",
            "text": "KZG commitments MUST match the corresponding blobs and cell_proofs (verified via compute_cells and verify_cell_kzg_proof_batch)."
          }
        ],
        "pre_conditions": [
          {
            "id": "PRE-7594-002",
            "text": "Blob transaction senders MUST compute cell proofs themselves and include them in the wrapper."
          }
        ],
        "post_conditions": [
          {
            "id": "POST-7594-003",
            "text": "The node MUST validate tx_payload_body and verify the wrapped data against it."
          }
        ],
        "state_variables": [
          {
            "id": "SV-7594-004",
            "name": "wrapper_version",
            "description": "One byte indicating wrapper version. Currently set to 1."
          }
        ],
        "functions": [
          {
            "id": "FN-7594-001",
            "signature": "compute_cells(blob) -> cells[]",
            "description": "Outputs all cells of a blob including extension cells."
          },
          {
            "id": "FN-7594-002",
            "signature": "verify_cell_kzg_proof_batch(commitments, cell_proofs) -> bool",
            "description": "Batch verifies all cell KZG proofs against their commitments."
          },
          {
            "id": "FN-7594-003",
            "signature": "kzg_to_versioned_hash(commitment) -> hash",
            "description": "Converts a KZG commitment to a versioned hash."
          }
        ],
        "data_structures": [
          {
            "id": "DS-7594-001",
            "name": "PooledTransactions wrapper",
            "definition": "rlp([tx_payload_body, wrapper_version, blobs, commitments, cell_proofs])",
            "description": "Modified transaction wrapper for gossip responses including cell proofs."
          }
        ]
      },
      {
        "id": "SG-7594-004",
        "name": "Withholding Attack Security Model",
        "description": "Formalizes the security of PeerDAS against data withholding attacks using a probabilistic bound. The probability of convincing a fraction epsilon of nodes that data is available when withheld decreases rapidly with network size.",
        "invariants": [
          {
            "id": "INV-7594-010",
            "text": "For mainnet parameters (10,000 nodes), the probability of a successful withholding attack drops to negligible (< 10^-20) when targeting more than 2% of nodes."
          }
        ],
        "pre_conditions": [],
        "post_conditions": [],
        "state_variables": [],
        "functions": [],
        "data_structures": []
      }
    ],
    "metadata": {
      "timestamp": "1770262049",
      "extraction_method": "subgraph-extractor",
      "worker_id": 0
    }
  },
  {
    "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7823.md",
    "title": "EIP-7823: Set Upper Bounds for MODEXP",
    "category": "EIP",
    "type": "Standards Track / Core",
    "layer": "execution",
    "status": "success",
    "sub_graphs": [
      {
        "id": "SG-7823-001",
        "name": "MODEXP Input Length Bound",
        "description": "Introduces an upper bound on MODEXP precompile inputs. Each of the three length inputs (length_of_BASE, length_of_EXPONENT, length_of_MODULUS) MUST be <= 8192 bits (1024 bytes).",
        "invariants": [
          {
            "id": "INV-7823-001",
            "text": "Each of length_of_BASE, length_of_EXPONENT, and length_of_MODULUS MUST be less than or equal to 8192 bits (1024 bytes)."
          },
          {
            "id": "INV-7823-002",
            "text": "If any input length exceeds the limit, the precompile execution MUST stop, return an error, and consume all gas."
          }
        ],
        "pre_conditions": [
          {
            "id": "PRE-7823-001",
            "text": "MODEXP precompile at address 0x05 accepts input in format: <length_of_BASE> <length_of_EXPONENT> <length_of_MODULUS> <BASE> <EXPONENT> <MODULUS> (per EIP-198)."
          }
        ],
        "post_conditions": [
          {
            "id": "POST-7823-001",
            "text": "Successful MODEXP execution only occurs when all input lengths are within the 1024-byte bound."
          },
          {
            "id": "POST-7823-002",
            "text": "Out-of-bound inputs result in error with full gas consumption."
          }
        ],
        "state_variables": [
          {
            "id": "SV-7823-001",
            "name": "MODEXP_INPUT_LIMIT",
            "description": "Maximum input field size: 8192 bits (1024 bytes)."
          }
        ],
        "functions": [
          {
            "id": "FN-7823-001",
            "signature": "MODEXP(base, exponent, modulus) -> result",
            "description": "Precompile at 0x05 now with upper bound enforcement on all three input lengths."
          }
        ],
        "data_structures": []
      }
    ],
    "metadata": {
      "timestamp": "1770262049",
      "extraction_method": "subgraph-extractor",
      "worker_id": 0
    }
  },
