    "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7825.md",
    "title": "EIP-7825: Transaction Gas Limit Cap",
    "category": "EIP",
    "type": "Standards Track / Core",
    "layer": "execution",
    "status": "success",
    "sub_graphs": [
      {
        "id": "SG-7825-001",
        "name": "Transaction Gas Limit Enforcement",
        "description": "Introduces a protocol-level cap on maximum gas per transaction to 16,777,216 (2^24). This cap applies regardless of block gas limit and is enforced at txpool validation and block validation.",
        "invariants": [
          {
            "id": "INV-7825-001",
            "text": "No single transaction may specify a gasLimit exceeding 16,777,216 (2^24) gas."
          },
          {
            "id": "INV-7825-002",
            "text": "The transaction gas cap is independent of the block gas limit."
          }
        ],
        "pre_conditions": [],
        "post_conditions": [
          {
            "id": "POST-7825-001",
            "text": "Transactions with gasLimit > 16,777,216 are invalidated and not included in the txpool."
          },
          {
            "id": "POST-7825-002",
            "text": "Blocks containing a transaction with gasLimit > 16,777,216 are deemed invalid and rejected."
          }
        ],
        "state_variables": [
          {
            "id": "SV-7825-001",
            "name": "MAX_TRANSACTION_GAS_LIMIT",
            "description": "Protocol-level maximum gas per transaction: 16,777,216 (2^24)."
          }
        ],
        "functions": [],
        "data_structures": [],
        "state_transitions": [
          {
            "id": "ST-7825-001",
            "description": "Txpool validation: if sender's gasLimit > 16,777,216, transaction is invalidated (MAX_GAS_LIMIT_EXCEEDED error)."
          },
          {
            "id": "ST-7825-002",
            "description": "Block validation: any block with a transaction having gasLimit > 16,777,216 is rejected as invalid."
          }
        ]
      }
    ],
    "metadata": {
      "timestamp": "1770262049",
      "extraction_method": "subgraph-extractor",
      "worker_id": 0
    }
  },
  {
    "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7883.md",
    "title": "EIP-7883: ModExp Gas Cost Increase",
    "category": "EIP",
    "type": "Standards Track / Core",
    "layer": "execution",
    "status": "success",
    "sub_graphs": [
      {
        "id": "SG-7883-001",
        "name": "ModExp Gas Pricing Algorithm Update",
        "description": "Modifies the EIP-2565 ModExp precompile pricing: increases minimum gas from 200 to 500, triples general cost (removes /3 divisor), and doubles cost for exponents >32 bytes (multiplier 8->16). Introduces minimum multiplication_complexity of 16 and doubles complexity for base/modulus >32 bytes.",
        "invariants": [
          {
            "id": "INV-7883-001",
            "text": "Minimum gas cost for MODEXP is 500 (increased from 200)."
          },
          {
            "id": "INV-7883-002",
            "text": "General cost is multiplication_complexity * iteration_count (no division by 3)."
          },
          {
            "id": "INV-7883-003",
            "text": "Minimum multiplication_complexity is 16 (for base/modulus <= 32 bytes)."
          },
          {
            "id": "INV-7883-004",
            "text": "For base/modulus > 32 bytes, multiplication_complexity = 2 * words^2."
          },
          {
            "id": "INV-7883-005",
            "text": "For exponents > 32 bytes, iteration_count multiplier is 16 (increased from 8)."
          }
        ],
        "pre_conditions": [
          {
            "id": "PRE-7883-001",
            "text": "Precompile at address 0x05 must be called with valid MODEXP inputs per EIP-198."
          }
        ],
        "post_conditions": [
          {
            "id": "POST-7883-001",
            "text": "Gas charged according to new formula: max(500, floor(multiplication_complexity * iteration_count))."
          }
        ],
        "state_variables": [],
        "functions": [
          {
            "id": "FN-7883-001",
            "signature": "calculate_multiplication_complexity(base_length, modulus_length) -> int",
            "description": "Returns min 16 for <=32 bytes, or 2*words^2 for >32 bytes, where words=ceil(max_length/8)."
          },
          {
            "id": "FN-7883-002",
            "signature": "calculate_iteration_count(exponent_length, exponent) -> int",
            "description": "Returns iteration count with 16x multiplier for exponent_length > 32 bytes (was 8x). Minimum return value is 1."
          },
          {
            "id": "FN-7883-003",
            "signature": "calculate_gas_cost(base_length, modulus_length, exponent_length, exponent) -> int",
            "description": "Returns max(500, floor(multiplication_complexity * iteration_count))."
          }
        ],
        "data_structures": []
      }
    ],
    "metadata": {
      "timestamp": "1770262049",
      "extraction_method": "subgraph-extractor",
      "worker_id": 0
    }
  },
  {
    "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7892.md",
    "title": "EIP-7892: Blob Parameter Only Hardforks",
    "category": "EIP",
    "type": "Informational",
    "layer": "consensus+execution",
    "status": "success",
    "sub_graphs": [
      {
        "id": "SG-7892-001",
        "name": "BPO Hardfork Definition and Configuration",
        "description": "Defines BPO (Blob Parameter Only) hardforks as protocol upgrades that modify only blob-related parameters (target, max, baseFeeUpdateFraction) through configuration without requiring client code changes.",
