  {
    "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7917.md",
    "title": "EIP-7917: Deterministic Proposer Lookahead",
    "category": "EIP",
    "type": "Standards Track / Core",
    "layer": "consensus",
    "status": "success",
    "sub_graphs": [
      {
        "id": "SG-7917-001",
        "name": "Proposer Lookahead State Extension",
        "description": "Extends BeaconState with a proposer_lookahead field: a vector of validator indices covering MIN_SEED_LOOKAHEAD + 1 epochs starting from the current epoch. Pre-calculated at epoch boundary.",
        "invariants": [
          {
            "id": "INV-7917-001",
            "text": "proposer_lookahead MUST be a Vector[ValidatorIndex, (MIN_SEED_LOOKAHEAD + 1) * SLOTS_PER_EPOCH]."
          },
          {
            "id": "INV-7917-002",
            "text": "proposer_lookahead[0] is the validator index for the first proposer in the current epoch."
          },
          {
            "id": "INV-7917-003",
            "text": "The lookahead for epoch N uses RANDAO from epoch N - MIN_SEED_LOOKAHEAD - 1 and effective balances from epoch N - MIN_SEED_LOOKAHEAD."
          },
          {
            "id": "INV-7917-004",
            "text": "It is no longer possible for validators to grind effective balances to manipulate the proposer schedule of the next epoch."
          }
        ],
        "pre_conditions": [
          {
            "id": "PRE-7917-001",
            "text": "The first block after fork must calculate all lookaheads for epochs up to MIN_SEED_LOOKAHEAD ahead."
          }
        ],
        "post_conditions": [
          {
            "id": "POST-7917-001",
            "text": "Next-epoch proposer schedule is fully deterministic and accessible via beacon root + Merkle proof."
          }
        ],
        "state_variables": [
          {
            "id": "SV-7917-001",
