            "signature": "get_beacon_proposer_index(state: BeaconState) -> ValidatorIndex",
            "description": "Returns proposer index from pre-calculated lookahead: state.proposer_lookahead[state.slot % SLOTS_PER_EPOCH]."
          },
          {
            "id": "FN-7917-002",
            "signature": "process_proposer_lookahead(state: BeaconState) -> None",
