        "description": "Imposes a reserve price on blobs by modifying calc_excess_blob_gas(). When BLOB_BASE_COST * base_fee_per_gas > GAS_PER_BLOB * base_fee_per_blob_gas, excess_blob_gas increases without subtracting target_blob_gas, preventing the blob fee from dropping below the execution cost floor.",
        "invariants": [
          {
            "id": "INV-7918-001",
            "text": "BLOB_BASE_COST = 2^13 (8192)."
          },
          {
            "id": "INV-7918-002",
            "text": "The reserve blob base fee is BLOB_BASE_COST * base_fee_per_gas / GAS_PER_BLOB."
          },
          {
            "id": "INV-7918-003",
            "text": "The ratio between reserve price and execution base fee is fixed at BLOB_BASE_COST / GAS_PER_BLOB = 1/16."
          },
          {
            "id": "INV-7918-004",
            "text": "The blob fee's share of total price is always at least BLOB_BASE_COST / (BLOB_BASE_COST + execution_cost)."
          },
          {
            "id": "INV-7918-005",
            "text": "The per-block maximum increase in excess_blob_gas remains unchanged."
          }
        ],
        "pre_conditions": [
