            "text": "EIP-4844 blob fee market must be active."
          },
          {
            "id": "PRE-7918-002",
            "text": "EIP-7840 blobSchedule for target, max, baseFeeUpdateFraction must be available."
          }
        ],
        "post_conditions": [
