            "id": "POST-7918-001",
            "text": "Blob consumers always pay at least a fraction (1/16) of the execution base fee for blob compute."
          },
          {
            "id": "POST-7918-002",
            "text": "The blob fee update mechanism can properly converge to equilibrium instead of falling to 1 wei."
          }
        ],
        "state_variables": [
          {
